package app.pulso.radio;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.net.*;
import android.os.*;
import androidx.core.app.NotificationCompat;
import androidx.core.content.FileProvider;
import org.json.*;
import java.io.*;
import java.net.*;
import java.security.MessageDigest;
import java.util.*;
public final class AppUpdater {
 private static final String ORIGIN="https://github.com/apllication/pulso-radio/releases/";
 private static final String MANIFEST=ORIGIN+"latest/download/update.json";
 private static long lastAttempt=0;
 private static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("pulso_native",Context.MODE_PRIVATE);}
 private static long code(PackageInfo p){return Build.VERSION.SDK_INT>=28?p.getLongVersionCode():p.versionCode;}
 private static HttpURLConnection open(String address)throws Exception{URL u=new URL(address);for(int i=0;i<6;i++){String host=u.getHost();if(!u.getProtocol().equals("https")||!(host.equals("github.com")||host.equals("release-assets.githubusercontent.com")||host.equals("objects.githubusercontent.com")))throw new IOException("Endereço de atualização inválido.");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Pulso-Android");int status=c.getResponseCode();if(status>=300&&status<400){String next=c.getHeaderField("Location");c.disconnect();if(next==null)throw new IOException();u=new URL(u,next);continue;}if(status!=200){c.disconnect();throw new IOException("Não foi possível consultar a atualização (HTTP "+status+").");}return c;}throw new IOException("Muitos redirecionamentos.");}
 private static String text(String url)throws Exception{HttpURLConnection c=open(url);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))>0){out.write(b,0,n);if(out.size()>64000)throw new IOException("Manifesto inválido.");}return out.toString("UTF-8");}finally{c.disconnect();}}
 public static synchronized JSONObject check(Context c,boolean force)throws Exception{long now=System.currentTimeMillis();boolean auto=prefs(c).getBoolean("autoUpdate",true);if(!force&&(!auto||now-Math.max(lastAttempt,prefs(c).getLong("lastUpdateCheck",0))<6*60*60*1000L)){String cached=prefs(c).getString("latestUpdate","");if(cached.isEmpty())return new JSONObject().put("available",false);return describe(c,new JSONObject(cached));}lastAttempt=now;prefs(c).edit().putLong("lastUpdateCheck",now).apply();JSONObject m=new JSONObject(text(MANIFEST));validate(m);prefs(c).edit().putString("latestUpdate",m.toString()).apply();JSONObject result=describe(c,m);if(result.optBoolean("available")){android.net.ConnectivityManager cm=(android.net.ConnectivityManager)c.getSystemService(Context.CONNECTIVITY_SERVICE);if(auto&&cm!=null&&cm.getActiveNetwork()!=null&&!cm.isActiveNetworkMetered())try{download(c,m);result.put("downloaded",true);}catch(Exception ignored){}notifyUpdate(c,m);}return result;}
 private static JSONObject describe(Context c,JSONObject m)throws Exception{return new JSONObject().put("available",m.getLong("versionCode")>code(c.getPackageManager().getPackageInfo(c.getPackageName(),0))).put("versionName",m.optString("versionName")).put("downloaded",new File(c.getCacheDir(),"updates/Pulso.apk").isFile()&&prefs(c).getString("downloadedSha","").equals(m.optString("sha256")));}
 private static void validate(JSONObject m)throws Exception{String url=m.optString("url"),sha=m.optString("sha256");if(m.optLong("versionCode")<=0||!sha.matches("[a-f0-9]{64}")||!url.startsWith(ORIGIN+"download/")||!url.endsWith(".apk")||!new URI(url).getHost().equals("github.com"))throw new IOException("Dados da atualização inválidos.");}
 private static Set<String> signatures(PackageInfo p)throws Exception{android.content.pm.Signature[] signatures=Build.VERSION.SDK_INT>=28?p.signingInfo.getApkContentsSigners():p.signatures;Set<String> values=new HashSet<>();for(android.content.pm.Signature s:signatures)values.add(hex(MessageDigest.getInstance("SHA-256").digest(s.toByteArray())));return values;}
 private static String hex(byte[] bytes){StringBuilder b=new StringBuilder();for(byte v:bytes)b.append(String.format(java.util.Locale.ROOT,"%02x",v&255));return b.toString();}
 private static void verify(Context c,File f,JSONObject m)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)digest.update(b,0,n);}if(!hex(digest.digest()).equals(m.getString("sha256")))throw new IOException("O arquivo baixado está incompleto. Tente novamente.");int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo installed=c.getPackageManager().getPackageInfo(c.getPackageName(),flags),apk=c.getPackageManager().getPackageArchiveInfo(f.getAbsolutePath(),flags);if(apk==null||!c.getPackageName().equals(apk.packageName)||code(apk)!=m.getLong("versionCode"))throw new IOException("Este APK não corresponde ao Pulso.");if(!signatures(installed).equals(signatures(apk)))throw new IOException("A assinatura é diferente da versão de teste. Não desinstale o app: preserve seu ID e contatos antes de migrar.");}
 private static synchronized File download(Context c,JSONObject m)throws Exception{validate(m);File folder=new File(c.getCacheDir(),"updates");if(!folder.isDirectory()&&!folder.mkdirs())throw new IOException("Não foi possível preparar o download.");File ready=new File(folder,"Pulso.apk");if(ready.isFile()&&prefs(c).getString("downloadedSha","").equals(m.getString("sha256"))){verify(c,ready,m);return ready;}File part=new File(folder,"Pulso.part");HttpURLConnection connection=open(m.getString("url"));try{try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(part)){byte[] buffer=new byte[16384];int n;long total=0;while((n=in.read(buffer))>0){total+=n;if(total>80*1024*1024)throw new IOException("APK muito grande.");out.write(buffer,0,n);}}verify(c,part,m);if(!part.renameTo(ready))throw new IOException("Não foi possível finalizar o download.");prefs(c).edit().putString("downloadedSha",m.getString("sha256")).apply();return ready;}finally{connection.disconnect();if(part.isFile())part.delete();}}
 public static File prepare(Context c)throws Exception{String raw=prefs(c).getString("latestUpdate","");if(raw.isEmpty()){check(c,true);raw=prefs(c).getString("latestUpdate","");}JSONObject m=new JSONObject(raw);if(!describe(c,m).optBoolean("available"))throw new IOException("O aplicativo já está atualizado.");return download(c,m);}
 public static void install(Activity activity,File file){if(Build.VERSION.SDK_INT>=26&&!activity.getPackageManager().canRequestPackageInstalls()){activity.startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())));return;}Uri uri=FileProvider.getUriForFile(activity,activity.getPackageName()+".fileprovider",file);Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);activity.startActivity(intent);}
 private static void notifyUpdate(Context c,JSONObject m){try{NotificationManager manager=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)manager.createNotificationChannel(new NotificationChannel("pulso_updates","Atualizações do Pulso",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(c,8,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);manager.notify(108,new NotificationCompat.Builder(c,"pulso_updates").setSmallIcon(R.drawable.ic_radio_notification).setContentTitle("Atualização do Pulso disponível").setContentText("Versão "+m.optString("versionName")+" · abra o menu para instalar").setContentIntent(open).setAutoCancel(true).build());}catch(Exception ignored){}}
}
